insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_education','education','noun','the process of teaching and learning, especially at school, college or university','[{"senseId":"education_1","meaning":"the process of teaching and learning, especially at school, college or university","acceptedParaphrases":["schooling","teaching and learning"],"masteryContexts":[{"contextId":"u10_01_education_meaning","text":"Her parents worked two jobs so that she could get a good education.","meaning":"teaching and learning that prepares a person for life","wrongMeanings":["a well-paid job that lasts for life","a large house in a safe area","a holiday abroad every summer"]},{"contextId":"u10_01_education_paraphrase","text":"The government has promised to spend more money on education next year.","meaning":"the system of schools, colleges and teaching","wrongMeanings":["the system of hospitals and clinics","the system of roads and railways","the system of police and courts"]}],"situationDistractors":["A family spent the whole weekend watching films on the sofa.","A man repaired the roof of his house after a storm.","A woman bought fresh vegetables at the market on Saturday.","A boy spent the afternoon painting a fence.","A woman queued at the post office to send a parcel.","A family cooked a large meal for a festival."],"gapDistractors":[{"contextId":"u10_01_education_gap_1","answer":"education","wrong":["employment","recreation","industry"]},{"contextId":"u10_01_education_gap_2","answer":"education","wrong":["recreation","loneliness","pronunciation"]},{"contextId":"u10_01_education_gap_3","answer":"education","wrong":["loneliness","intonation","recreation"]}],"spellingErrors":["educasion","eduction","educatoin","edducation","educaton","edjucation"],"wordFamilyForms":[{"form":"education","partOfSpeech":"noun","example":"Every child deserves a good education.","pedagogicallyUseful":true},{"form":"educate","partOfSpeech":"verb","example":"The campaign aims to educate young people about healthy eating.","pedagogicallyUseful":true,"altExample":"Schools should educate children about online safety."},{"form":"educational","partOfSpeech":"adjective","example":"The museum offers educational tours for school groups.","pedagogicallyUseful":true,"altExample":"My little brother loves educational games about animals."}],"masteryPassages":[{"passageId":"u10_01_education_passage_1","contextId":"u10_01_education_gap_1","text":"In the past, many girls in the village had to leave school at twelve. Today, every child receives a free ____ until the age of eighteen.","answer":"education"},{"passageId":"u10_01_education_passage_2","contextId":"u10_01_education_gap_2","text":"Her grandparents never learned to read. They worked hard so that their children could have the ____ they never had.","answer":"education"}],"contextDependentParaphrases":[],"wrongParaphrases":["employment","relaxation","punishment"],"misleadingDistractors":["the process of finding a job after leaving school","the money a government spends on hospitals","the free time people spend relaxing at weekends"],"teacherNote":"Noun: the process of teaching and learning (a good education, free education, primary/secondary education). Usually uncountable; \"a good education\" is the common countable use. The verb educate, the adjective educational and the adjective educated are taught in the Word Family pathway."}]'::jsonb,'["educate","educational"]'::jsonb,'["a good education","free education","access to education"]'::jsonb,'live'),
('vocab_higher_education','higher education','noun','study at a university or college after leaving secondary school','[{"senseId":"higher_education_1","meaning":"study at a university or college after leaving secondary school","acceptedParaphrases":["university study","study after school at a college or university"],"masteryContexts":[{"contextId":"u10_02_higher_education_meaning","text":"Many students take a gap year before they start higher education.","meaning":"study at university or college after school","wrongMeanings":["full-time work after leaving school","a long holiday travelling abroad","training to become a driver"]},{"contextId":"u10_02_higher_education_paraphrase","text":"The government gives loans to help students pay for higher education.","meaning":"degree-level courses at universities and colleges","wrongMeanings":["lessons for children under eleven","courses run by employers at work","evening clubs for retired people"]}],"situationDistractors":["A six-year-old learned to count to a hundred at primary school.","A teenager left school at sixteen and started working in a shop.","A grandmother joined a weekend class to learn to swim.","A nine-year-old learned his times tables.","A girl started her first job at sixteen in a café.","A toddler learned to say her first words."],"gapDistractors":[{"contextId":"u10_02_higher_education_gap_1","answer":"higher education","wrong":["primary school","loneliness","recreation"]},{"contextId":"u10_02_higher_education_gap_2","answer":"higher education","wrong":["recreation","pronunciation","loneliness"]},{"contextId":"u10_02_higher_education_gap_3","answer":"higher education","wrong":["intonation","recreation","pronunciation"]}],"spellingErrors":["higher educasion","hier education","higher eduction","hiher education","higher educaton","highre education"],"masteryPassages":[{"passageId":"u10_02_higher_education_passage_1","contextId":"u10_02_higher_education_gap_1","text":"After their final school exams, students have a choice. Some start work, while others go on to ____ at a university or college.","answer":"higher education"},{"passageId":"u10_02_higher_education_passage_2","contextId":"u10_02_higher_education_gap_2","text":"University fees have risen sharply. Some families now worry that ____ is becoming too expensive for ordinary students.","answer":"higher education"}],"contextDependentParaphrases":[],"wrongParaphrases":["primary school study","training at work","evening classes for children"],"misleadingDistractors":["the first years of school for young children","training that happens only at work","lessons for adults who cannot read"],"teacherNote":"Noun phrase: education at university or college level, after secondary school (go into higher education, a place in higher education, the cost of higher education). Uncountable. Boundary: \"further education\" in the UK is usually college study that is not at degree level; only higher education is taught here."}]'::jsonb,'[]'::jsonb,'["go into higher education","a place in higher education","the cost of higher education"]'::jsonb,'live'),
('vocab_university','university','noun','an institution where students study for degrees and where academic research is done','[{"senseId":"university_1","meaning":"an institution where students study for degrees and where academic research is done","acceptedParaphrases":["a place where students study for a degree","an institution for higher study"],"masteryContexts":[{"contextId":"u10_03_university_meaning","text":"After three years at university, he graduated with a degree in history.","meaning":"a place where people study for a degree","wrongMeanings":["a place where young children start school","a company where people train as drivers","a building where people borrow books"]},{"contextId":"u10_03_university_paraphrase","text":"The university has one of the best medical research centres in the world.","meaning":"an institution where academic research is carried out","wrongMeanings":["a hospital where patients are treated","a factory where medicines are made","a shop where science equipment is sold"]}],"situationDistractors":["A boy started his first day at nursery and cried when his mother left.","A woman took six driving lessons before she passed her test.","A man worked as a cashier in a supermarket for ten years.","A girl bought a ticket at the train station.","A man trained a puppy to sit.","A child played in the sandpit at kindergarten."],"gapDistractors":[{"contextId":"u10_03_university_gap_1","answer":"university","wrong":["interview","opinion","industry"]},{"contextId":"u10_03_university_gap_2","answer":"university","wrong":["interview","opinion","loneliness"]},{"contextId":"u10_03_university_gap_3","answer":"university","wrong":["opinion","intonation","preference"]}],"spellingErrors":["univercity","universaty","unniversity","universiti","univeristy","univesity"],"masteryPassages":[{"passageId":"u10_03_university_passage_1","contextId":"u10_03_university_gap_1","text":"My sister wants to become a doctor. Next year she will start a six-year medical degree at ____.","answer":"university"},{"passageId":"u10_03_university_passage_2","contextId":"u10_03_university_gap_2","text":"The professor has worked at the same ____ for thirty years. She teaches students and leads a team of scientists.","answer":"university"}],"contextDependentParaphrases":[],"wrongParaphrases":["a place where children start school","a place where people buy books","a place where people learn to drive"],"misleadingDistractors":["a school for children aged five to eleven","a company that trains people to drive","a building where old books are sold"],"teacherNote":"Noun: an institution for degree-level study and research (go to university, at university, a university degree). Note \"a university\" (the first sound is /j/, so not *an university) and the British phrase \"go to university\" with no article. The adjective academic is the related word learners need."}]'::jsonb,'[]'::jsonb,'["go to university","a university degree","apply to university"]'::jsonb,'live'),
('vocab_academic_10','academic','adjective','connected with education, studying and schoolwork, especially at a high level','[{"senseId":"academic_10_1","meaning":"connected with education, studying and schoolwork, especially at a high level","acceptedParaphrases":["connected with studying","related to schoolwork"],"masteryContexts":[{"contextId":"u10_04_academic_10_meaning","text":"The academic year in our school starts in September and ends in June.","meaning":"connected with the period when teaching takes place","wrongMeanings":["connected with the period of school holidays","connected with the period of sports matches","connected with the period of exams only"]},{"contextId":"u10_04_academic_10_paraphrase","text":"Some students are good at academic subjects like maths, while others prefer art or sport.","meaning":"connected with study and theory rather than practical skills","wrongMeanings":["connected with practical skills and making things","connected with sport and physical fitness","connected with art and creative activities"]}],"situationDistractors":["A boy spent his Saturday playing football with his cousins.","A woman opened a café and spent the day serving customers.","A group of friends went to the cinema after school.","A girl practised tricks on her skateboard.","A man repaired a leaking tap.","A family went shopping for new shoes."],"gapDistractors":[{"contextId":"u10_04_academic_10_gap_1","answer":"academic","wrong":["reluctant","cosmopolitan","overseas"]},{"contextId":"u10_04_academic_10_gap_2","answer":"academic","wrong":["reluctant","cosmopolitan","lonely"]},{"contextId":"u10_04_academic_10_gap_3","answer":"academic","wrong":["reluctant","cosmopolitan","overseas"]}],"spellingErrors":["academmic","acadamic","academik","accademic","academc","acedemic"],"wordFamilyForms":[{"form":"academic","partOfSpeech":"adjective","example":"Her academic results have improved this year.","pedagogicallyUseful":true},{"form":"academy","partOfSpeech":"noun","example":"He trained at a famous football academy in Madrid.","pedagogicallyUseful":true,"altExample":"She studies dance at a performing arts academy."},{"form":"academically","partOfSpeech":"adverb","example":"The school is academically successful and sends many students to university.","pedagogicallyUseful":true,"altExample":"He is academically gifted but finds sport difficult."}],"masteryPassages":[{"passageId":"u10_04_academic_10_passage_1","contextId":"u10_04_academic_10_gap_1","text":"Tom is brilliant at sport and music. However, his ____ results in maths and science are disappointing.","answer":"academic"},{"passageId":"u10_04_academic_10_passage_2","contextId":"u10_04_academic_10_gap_2","text":"In Britain, the ____ year begins in September. It ends with exams in the early summer.","answer":"academic"}],"contextDependentParaphrases":[],"wrongParaphrases":["connected with sport","related to money","connected with friends"],"misleadingDistractors":["connected with sport and exercise","related to earning money","connected with friends and free time"],"teacherNote":"Adjective: connected with education and study (academic results, academic subjects, the academic year, academic writing). Unit 10 uses it for school and university study; Unit 6 taught it for study skills. Boundary: academic is about study, not practical skills (vocational). The noun academy and the adverb academically are taught in the Word Family pathway."}]'::jsonb,'["academy","academically"]'::jsonb,'["academic results","the academic year","academic writing"]'::jsonb,'live'),
('vocab_recreation','recreation','noun','activities that people do for enjoyment when they are not working or studying','[{"senseId":"recreation_1","meaning":"activities that people do for enjoyment when they are not working or studying","acceptedParaphrases":["leisure activities","free-time activities"],"masteryContexts":[{"contextId":"u10_05_recreation_meaning","text":"The lake is used for recreation, such as swimming, fishing and sailing.","meaning":"activities done for enjoyment","wrongMeanings":["work done to earn money","travel from one place to another","cleaning and repairing the lake"]},{"contextId":"u10_05_recreation_paraphrase","text":"Students need time for recreation as well as for study.","meaning":"free time spent doing enjoyable things","wrongMeanings":["time spent doing extra homework","time spent working at a part-time job","time spent sleeping and resting"]}],"situationDistractors":["A student sat an exam in the school hall for three hours.","A man worked overtime at the factory to earn extra money.","A girl cleaned the kitchen floor because her mother asked her to.","A woman filled in her tax forms.","A boy did his chores before dinner.","A student revised for a test all evening."],"gapDistractors":[{"contextId":"u10_05_recreation_gap_1","answer":"recreation","wrong":["assessment","employment","examination"]},{"contextId":"u10_05_recreation_gap_2","answer":"recreation","wrong":["assessment","qualification","examination"]},{"contextId":"u10_05_recreation_gap_3","answer":"recreation","wrong":["assessment","employment","qualification"]}],"spellingErrors":["recreasion","recration","reccreation","recreaton","recriation","recreatoin"],"masteryPassages":[{"passageId":"u10_05_recreation_passage_1","contextId":"u10_05_recreation_gap_1","text":"The old factory site has been turned into a park. It now provides space for walking, football and other kinds of ____.","answer":"recreation"},{"passageId":"u10_05_recreation_passage_2","contextId":"u10_05_recreation_gap_2","text":"Students work hard all week. They also need time for ____, such as sport, music or meeting friends.","answer":"recreation"}],"contextDependentParaphrases":[],"wrongParaphrases":["paid activities","school lessons","household jobs"],"misleadingDistractors":["work that people do to earn money","lessons that students must attend","jobs that people do at home, like cleaning"],"teacherNote":"Noun: activities done for enjoyment in free time (sport and recreation, a recreation centre, recreation ground). Uncountable. Boundary: recreation is enjoyable free-time activity; relaxation is resting and becoming calm. The adjective recreational is taught in the Word Family pathway."}]'::jsonb,'[]'::jsonb,'["sport and recreation","a recreation centre","a form of recreation"]'::jsonb,'live'),
('vocab_literacy','literacy','noun','the ability to read and write','[{"senseId":"literacy_1","meaning":"the ability to read and write","acceptedParaphrases":["the ability to read and write","reading and writing skills"],"masteryContexts":[{"contextId":"u10_06_literacy_meaning","text":"In the region, literacy rates have risen quickly since every village got its own school.","meaning":"the ability to read and write","wrongMeanings":["the number of people who have jobs","the number of people who own cars","the number of people who speak two languages"]},{"contextId":"u10_06_literacy_paraphrase","text":"The course teaches digital literacy, such as how to check if a website is reliable.","meaning":"knowledge and skills in a particular area","wrongMeanings":["the ability to build your own computer","the habit of spending hours online","the speed at which you can type"]}],"situationDistractors":["A girl practised the violin every evening for her concert.","A boy ran around the track five times to improve his fitness.","A family planted tomatoes and beans in their garden.","A boy learned to ride a bike without stabilisers.","A girl practised her tennis serve.","A man fixed a puncture on his car."],"gapDistractors":[{"contextId":"u10_06_literacy_gap_1","answer":"literacy","wrong":["recreation","industry","loneliness"]},{"contextId":"u10_06_literacy_gap_2","answer":"literacy","wrong":["loneliness","employment","industry"]},{"contextId":"u10_06_literacy_gap_3","answer":"literacy","wrong":["recreation","loneliness","industry"]}],"spellingErrors":["literasy","litteracy","literacey","literecy","litracy","litaracy"],"wordFamilyForms":[{"form":"literacy","partOfSpeech":"noun","example":"The charity works to improve adult literacy.","pedagogicallyUseful":true},{"form":"literate","partOfSpeech":"adjective","example":"By the age of seven, most children are fully literate.","pedagogicallyUseful":true,"altExample":"Almost every adult in the country is now literate."},{"form":"illiterate","partOfSpeech":"adjective","example":"Many of the villagers were illiterate until the school opened.","pedagogicallyUseful":true,"altExample":"Her great-grandmother was illiterate and signed her name with a cross."}],"masteryPassages":[{"passageId":"u10_06_literacy_passage_1","contextId":"u10_06_literacy_gap_1","text":"Thirty years ago, only half the adults in the region could read a newspaper. Thanks to evening classes, ____ has improved dramatically.","answer":"literacy"},{"passageId":"u10_06_literacy_passage_2","contextId":"u10_06_literacy_gap_2","text":"Children who are read to every night usually learn to read sooner. Parents play a huge part in developing early ____.","answer":"literacy"}],"contextDependentParaphrases":[],"wrongParaphrases":["the ability to count and measure","the ability to speak clearly","the ability to draw well"],"misleadingDistractors":["the ability to speak several languages","the ability to do difficult sums","the habit of reading only for fun"],"teacherNote":"Noun: the ability to read and write (literacy rates, adult literacy, literacy skills). By extension, knowledge of a particular area (digital literacy, media literacy). Uncountable. The adjectives literate and illiterate are taught in the Word Family pathway."}]'::jsonb,'["literate","illiterate"]'::jsonb,'["adult literacy","literacy skills","digital literacy"]'::jsonb,'live'),
('vocab_assessment','assessment','noun','the process of judging how well someone has learned or done something, or a test used to do this','[{"senseId":"assessment_1","meaning":"the process of judging how well someone has learned or done something, or a test used to do this","acceptedParaphrases":["an evaluation","a judgement of how well someone has done"],"masteryContexts":[{"contextId":"u10_07_assessment_meaning","text":"The course has no final exam; instead there is continuous assessment of your coursework.","meaning":"judging how well students are doing","wrongMeanings":["explaining new topics to students","giving students extra homework","choosing which students can join a course"]},{"contextId":"u10_07_assessment_paraphrase","text":"The doctor made a quick assessment of the injured player before he went back on the pitch.","meaning":"a judgement of how good or bad something is","wrongMeanings":["a treatment given for an injury","a decision to stop the game","a medicine to reduce pain"]}],"situationDistractors":["A teacher read a funny story to her class at the end of the day.","A student chose a new pencil case in the school shop.","A class went on a trip to the zoo without any worksheets.","A class sang songs on the last day of term.","A student decorated the classroom for a party.","A teacher gave out free fruit at break."],"gapDistractors":[{"contextId":"u10_07_assessment_gap_1","answer":"assessment","wrong":["loneliness","recreation","literacy"]},{"contextId":"u10_07_assessment_gap_2","answer":"assessment","wrong":["loneliness","recreation","industry"]},{"contextId":"u10_07_assessment_gap_3","answer":"assessment","wrong":["loneliness","recreation","literacy"]}],"spellingErrors":["assesment","asessment","assessmant","asesment","assesmant","assessmet"],"wordFamilyForms":[{"form":"assessment","partOfSpeech":"noun","example":"The final assessment is a speaking test.","pedagogicallyUseful":true},{"form":"assess","partOfSpeech":"verb","example":"Teachers assess each project using the same criteria.","pedagogicallyUseful":true,"altExample":"The nurse will assess how serious the injury is."},{"form":"assessor","partOfSpeech":"noun","example":"An external assessor will visit to check the marking.","pedagogicallyUseful":true,"altExample":"The assessor watched each candidate give a short speech."}],"masteryPassages":[{"passageId":"u10_07_assessment_passage_1","contextId":"u10_07_assessment_gap_1","text":"There is no final exam on this course. Instead, your teachers will mark your projects throughout the year as part of continuous ____.","answer":"assessment"},{"passageId":"u10_07_assessment_passage_2","contextId":"u10_07_assessment_gap_2","text":"The coach watched each player carefully during training. He then gave an honest ____ of their strengths and weaknesses.","answer":"assessment"}],"contextDependentParaphrases":[],"wrongParaphrases":["an explanation","a punishment","a celebration"],"misleadingDistractors":["a list of rules for students to follow","a lesson in which a teacher explains new grammar","a prize given to the best student"],"teacherNote":"Noun: the process of judging someone’s learning or ability, or a test used for this (continuous assessment, a written assessment, an assessment of). Countable and uncountable. Boundary: an assessment can be any task that measures learning; an examination is a formal test, usually at the end of a course. The verb assess is taught in the Word Family pathway."}]'::jsonb,'["assess","assessor"]'::jsonb,'["continuous assessment","a written assessment","an assessment of"]'::jsonb,'live'),
('vocab_international_crisis','international crisis','noun','a serious and dangerous situation that affects many countries at the same time','[{"senseId":"international_crisis_1","meaning":"a serious and dangerous situation that affects many countries at the same time","acceptedParaphrases":["a global emergency","a serious problem affecting many countries"],"masteryContexts":[{"contextId":"u10_08_international_crisis_meaning","text":"World leaders met in Geneva to discuss how to end the international crisis.","meaning":"a dangerous situation affecting many countries","wrongMeanings":["a celebration involving many countries","a sports competition between nations","a friendly meeting of world leaders"]},{"contextId":"u10_08_international_crisis_paraphrase","text":"When the war began, millions of people had to leave their homes, and it soon became an international crisis.","meaning":"a serious emergency that needs action from many nations","wrongMeanings":["a small local problem that ends quickly","a festival that welcomes visitors","a trade agreement between two countries"]}],"situationDistractors":["Two neighbours argued about where to park their cars.","A village held a summer fair with music and games.","A football team lost an important match in the final minute.","A cat got stuck up a tree in a garden.","A school changed the colour of its uniform.","A shop closed early on a Sunday."],"gapDistractors":[{"contextId":"u10_08_international_crisis_gap_1","answer":"international crisis","wrong":["interview","opinion","achievement"]},{"contextId":"u10_08_international_crisis_gap_2","answer":"international crisis","wrong":["interview","achievement","opportunity"]},{"contextId":"u10_08_international_crisis_gap_3","answer":"international crisis","wrong":["interview","achievement","opinion"]}],"spellingErrors":["internatinal crisis","internashional crisis","international crysis","internatonal crisis","international crisiss","interntional crisis"],"masteryPassages":[{"passageId":"u10_08_international_crisis_passage_1","contextId":"u10_08_international_crisis_gap_1","text":"The disease spread from one country to another within weeks. Governments everywhere had to respond to the growing ____.","answer":"international crisis"},{"passageId":"u10_08_international_crisis_passage_2","contextId":"u10_08_international_crisis_gap_2","text":"Millions of people left their homes after the war began. World leaders met urgently to discuss the ____.","answer":"international crisis"}],"contextDependentParaphrases":[],"wrongParaphrases":["a local celebration","a minor argument","a trade agreement"],"misleadingDistractors":["a small disagreement between two neighbours","a festival celebrated in many countries","a meeting where countries sign a trade deal"],"teacherNote":"Noun phrase: a serious, dangerous situation affecting many countries (cause / face / respond to an international crisis). Countable: crisis, plural crises. Boundary: a crisis is serious and needs urgent action; a problem can be small. The adjective critical and the word international are not separately taught here."}]'::jsonb,'[]'::jsonb,'["cause an international crisis","respond to an international crisis","a growing international crisis"]'::jsonb,'live'),
('vocab_digital_device','digital device','noun','a piece of electronic equipment such as a phone, tablet or laptop','[{"senseId":"digital_device_1","meaning":"a piece of electronic equipment such as a phone, tablet or laptop","acceptedParaphrases":["an electronic gadget","a phone, tablet or computer"],"masteryContexts":[{"contextId":"u10_09_digital_device_meaning","text":"Children who spend too long on a digital device before bed often sleep badly.","meaning":"an electronic machine such as a phone or tablet","wrongMeanings":["a printed book or magazine","a board game played with friends","a cup of hot milk"]},{"contextId":"u10_09_digital_device_paraphrase","text":"The library lends a digital device to any student who does not have a computer at home.","meaning":"a piece of electronic equipment like a laptop","wrongMeanings":["a paper notebook and pen","a printed dictionary","a desk and chair"]}],"situationDistractors":["A girl read a paperback novel on the train.","A man chopped onions with a sharp knife.","A farmer used a tractor to plough his field.","A girl wrote a letter with a fountain pen.","A boy hit a ball with a wooden bat.","A man swept the floor with a broom."],"gapDistractors":[{"contextId":"u10_09_digital_device_gap_1","answer":"digital device","wrong":["qualification","opinion","achievement"]},{"contextId":"u10_09_digital_device_gap_2","answer":"digital device","wrong":["qualification","opinion","achievement"]},{"contextId":"u10_09_digital_device_gap_3","answer":"digital device","wrong":["opinion","achievement","preference"]}],"spellingErrors":["digital devise","digitel device","digital devic","dijital device","digital deivce","diggital device"],"masteryPassages":[{"passageId":"u10_09_digital_device_passage_1","contextId":"u10_09_digital_device_gap_1","text":"Phones, tablets and laptops must be switched off before the exam begins. Any student found using a ____ will be asked to leave.","answer":"digital device"},{"passageId":"u10_09_digital_device_passage_2","contextId":"u10_09_digital_device_gap_2","text":"The library now lends out tablets. Students who do not own a ____ can borrow one for a week.","answer":"digital device"}],"contextDependentParaphrases":[],"wrongParaphrases":["a paper notebook","a kitchen tool","a garden machine"],"misleadingDistractors":["a printed book or magazine","a tool used in the kitchen","a machine used on a farm"],"teacherNote":"Noun phrase: an electronic machine such as a smartphone, tablet, laptop or e-reader (use / switch off a digital device). Countable. Common in school rules and articles about screen time. Boundary: a device is a piece of equipment made for a purpose; a digital device processes information electronically."}]'::jsonb,'[]'::jsonb,'["use a digital device","switch off a digital device","a portable digital device"]'::jsonb,'live'),
('vocab_progress','progress','noun','movement towards achieving something or improving','[{"senseId":"progress_1","meaning":"movement towards achieving something or improving","acceptedParaphrases":["improvement","development towards a goal"],"masteryContexts":[{"contextId":"u10_10_progress_meaning","text":"After a month of daily practice, Ali made rapid progress with his pronunciation.","meaning":"improvement in a skill","wrongMeanings":["loss of a skill through lack of practice","a test of a skill","a prize for a skill"]},{"contextId":"u10_10_progress_paraphrase","text":"Work on the new school building is making slow progress because of the rain.","meaning":"forward movement towards finishing something","wrongMeanings":["backward movement away from finishing","damage caused by bad weather","money spent on materials"]}],"situationDistractors":["A student forgot everything she had learned after the holiday.","A boy got the same low score on every test all year.","A builder stopped work on a house and left it unfinished for years.","A runner finished last in every race all season.","A plant stopped growing and died.","A student repeated the same mistake every week."],"gapDistractors":[{"contextId":"u10_10_progress_gap_1","answer":"progress","wrong":["loneliness","recreation","industry"]},{"contextId":"u10_10_progress_gap_2","answer":"progress","wrong":["loneliness","recreation","literacy"]},{"contextId":"u10_10_progress_gap_3","answer":"progress","wrong":["loneliness","recreation","intonation"]}],"spellingErrors":["progres","proggress","progess","prograss","progrese","porgress"],"wordFamilyForms":[{"form":"progress","partOfSpeech":"noun","example":"The class has made good progress this term.","pedagogicallyUseful":true},{"form":"progressive","partOfSpeech":"adjective","example":"The school is known for its progressive teaching methods.","pedagogicallyUseful":true,"altExample":"The new head teacher has very progressive ideas about homework."},{"form":"progression","partOfSpeech":"noun","example":"The course offers a clear progression from beginner to advanced level.","pedagogicallyUseful":true,"altExample":"There is a natural progression from the first conditional to the second."}],"masteryPassages":[{"passageId":"u10_10_progress_passage_1","contextId":"u10_10_progress_gap_1","text":"At the start of the year, Lina could not swim at all. Now she can swim fifty metres, so her teacher is delighted with her ____.","answer":"progress"},{"passageId":"u10_10_progress_passage_2","contextId":"u10_10_progress_gap_2","text":"The builders started work on the new library in March. Because of heavy rain, ____ has been slower than expected.","answer":"progress"}],"contextDependentParaphrases":[],"wrongParaphrases":["decline","delay","rest"],"misleadingDistractors":["a sudden loss of interest in something","the result of a single exam","a period of rest after hard work"],"teacherNote":"Noun: improvement or movement towards a goal (make progress, good progress, a progress report). Uncountable: not *a progress or *progresses. The verb progress (stress on the second syllable) and the adjective progressive are taught in the Word Family pathway."}]'::jsonb,'["progressive","progression"]'::jsonb,'["make progress","good progress","a progress report"]'::jsonb,'live')
insert into public.vocabulary_unit_occurrences
(occurrence_id,vocabulary_id,unit_number,unit_title,set_number,position_in_unit,sense_id,status,active)
values
