('u10_idea_education',10,'idea_set','{"originalIdea":"Her parents worked hard so that she could have a good education.","accurateParaphrases":["Her parents worked hard so that she could go to good schools and learn well.","She was able to study at good schools because her parents worked hard.","Thanks to her parents’ hard work, she received good schooling."],"meaningInvariants":[{"type":"meaning","value":"good schooling"}],"distractors":[{"text":"Her parents worked hard so that she could have a good job.","misconceptionCategory":"meaning_confusion"},{"text":"She worked hard so that her parents could have a good education.","misconceptionCategory":"role_reversal"},{"text":"Her parents did not work, so she had a poor education.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_education"],"primaryEvidenceTargetId":"vocab_education"}'::jsonb,'live'),
('u10_idea_higher_education',10,'idea_set','{"originalIdea":"More than half of the students in our school go on to higher education.","accurateParaphrases":["Over fifty per cent of our students continue their studies at university or college.","Most students from our school carry on studying at university level after they leave.","More than half of our school leavers start degree courses."],"meaningInvariants":[{"type":"quantity","value":"more than half"}],"distractors":[{"text":"More than half of the students in our school start full-time work after leaving.","misconceptionCategory":"meaning_confusion"},{"text":"Only a few students in our school go on to university or college.","misconceptionCategory":"quantity_change"},{"text":"More than half of the students in our school used to go to university.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_higher_education"],"primaryEvidenceTargetId":"vocab_higher_education"}'::jsonb,'live'),
('u10_idea_university',10,'idea_set','{"originalIdea":"My brother is studying engineering at a university in Scotland.","accurateParaphrases":["My brother is doing an engineering degree in Scotland.","In Scotland, my brother is taking a degree course in engineering.","My brother attends a degree-level institution in Scotland, where he studies engineering."],"meaningInvariants":[{"type":"meaning","value":"degree-level study"}],"distractors":[{"text":"My brother is working as an engineer at a factory in Scotland.","misconceptionCategory":"meaning_confusion"},{"text":"My brother is teaching engineering at a primary school in Scotland.","misconceptionCategory":"role_change"},{"text":"My brother will study engineering in Scotland next year.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_university"],"primaryEvidenceTargetId":"vocab_university"}'::jsonb,'live'),
('u10_idea_academic',10,'idea_set','{"originalIdea":"Tom is brilliant at sport, but his academic results are disappointing.","accurateParaphrases":["Tom is excellent at sport, but his marks in school subjects are poor.","Although Tom is great at sport, he does badly in his studies.","Tom’s exam results are disappointing, even though he is very good at sport."],"meaningInvariants":[{"type":"contrast","value":"good at sport, poor at study"}],"distractors":[{"text":"Tom is brilliant at sport, and his school results are excellent.","misconceptionCategory":"polarity_change"},{"text":"Tom is poor at sport, but his school results are excellent.","misconceptionCategory":"comparison_reversal"},{"text":"Tom is brilliant at sport, but his football results are disappointing.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_academic_10"],"primaryEvidenceTargetId":"vocab_academic_10"}'::jsonb,'live'),
('u10_idea_recreation',10,'idea_set','{"originalIdea":"The new park provides space for sport and recreation.","accurateParaphrases":["The new park gives people room to play sport and enjoy their free time.","People can use the new park for exercise and leisure activities.","The new park is a place where people can relax and do sport."],"meaningInvariants":[{"type":"meaning","value":"free-time enjoyment"}],"distractors":[{"text":"The new park provides space for sport and car parking.","misconceptionCategory":"meaning_confusion"},{"text":"The new park provides no space for sport or free-time activities.","misconceptionCategory":"polarity_change"},{"text":"The old park provided space for sport and free-time activities.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_recreation"],"primaryEvidenceTargetId":"vocab_recreation"}'::jsonb,'live'),
('u10_idea_literacy',10,'idea_set','{"originalIdea":"Evening classes have greatly improved adult literacy in the region.","accurateParaphrases":["Thanks to evening classes, many more adults in the region can now read and write.","Adults in the area read and write much better because of evening classes.","Night classes have helped local adults learn to read and write."],"meaningInvariants":[{"type":"meaning","value":"reading and writing"}],"distractors":[{"text":"Evening classes have greatly improved adult fitness in the region.","misconceptionCategory":"meaning_confusion"},{"text":"Evening classes have slightly improved children’s reading in the region.","misconceptionCategory":"degree_change"},{"text":"Evening classes have not changed how well adults in the region can read.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_literacy"],"primaryEvidenceTargetId":"vocab_literacy"}'::jsonb,'live'),
('u10_idea_assessment',10,'idea_set','{"originalIdea":"On this course, there is continuous assessment instead of a final exam.","accurateParaphrases":["This course has no final exam; your work is marked throughout the year.","Instead of one exam at the end, students on this course are judged on their work all year.","Your grade on this course comes from regular checks of your work, not an end-of-year test."],"meaningInvariants":[{"type":"contrast","value":"regular marking, not one exam"}],"distractors":[{"text":"On this course, there is a final exam instead of regular marking.","misconceptionCategory":"comparison_reversal"},{"text":"On this course, there is continuous teaching instead of a final exam.","misconceptionCategory":"meaning_confusion"},{"text":"On this course, there is both a final exam and regular marking.","misconceptionCategory":"detail_change"}],"linkedVocabularyIds":["vocab_assessment"],"primaryEvidenceTargetId":"vocab_assessment"}'::jsonb,'live'),
('u10_idea_international_crisis',10,'idea_set','{"originalIdea":"The spread of the disease quickly became an international crisis.","accurateParaphrases":["The disease spread so fast that it soon became a serious emergency for many countries.","Before long, the spread of the disease was a dangerous problem for the whole world.","Many nations were soon facing a serious emergency because the disease spread so quickly."],"meaningInvariants":[{"type":"meaning","value":"serious emergency affecting many countries"}],"distractors":[{"text":"The spread of the disease quickly became a local problem in one village.","misconceptionCategory":"scope_change"},{"text":"The spread of the disease slowly became a minor concern for one country.","misconceptionCategory":"degree_change"},{"text":"The spread of the disease quickly led to an international festival.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_international_crisis"],"primaryEvidenceTargetId":"vocab_international_crisis"}'::jsonb,'live'),
('u10_idea_digital_device',10,'idea_set','{"originalIdea":"Students may not use any digital device during the exam.","accurateParaphrases":["Phones, tablets and laptops are not allowed during the exam.","During the exam, students must not use any electronic equipment.","No electronic gadgets may be used by students while the exam is taking place."],"meaningInvariants":[{"type":"meaning","value":"no electronic equipment"}],"distractors":[{"text":"Students must use a digital device during the exam.","misconceptionCategory":"polarity_change"},{"text":"Students may not use any pens or paper during the exam.","misconceptionCategory":"meaning_confusion"},{"text":"Teachers may not use any electronic equipment during the exam.","misconceptionCategory":"role_change"}],"linkedVocabularyIds":["vocab_digital_device"],"primaryEvidenceTargetId":"vocab_digital_device"}'::jsonb,'live'),
('u10_idea_progress',10,'idea_set','{"originalIdea":"Ali has made rapid progress with his English this term.","accurateParaphrases":["Ali’s English has improved quickly this term.","This term, Ali has got much better at English in a short time.","Ali’s English has developed fast over the last few months."],"meaningInvariants":[{"type":"meaning","value":"quick improvement"}],"distractors":[{"text":"Ali has made slow progress with his English this term.","misconceptionCategory":"degree_change"},{"text":"Ali’s English has got worse this term.","misconceptionCategory":"polarity_change"},{"text":"Ali made rapid progress with his English last year.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_progress"],"primaryEvidenceTargetId":"vocab_progress"}'::jsonb,'live'),
('u10_idea_encourage',10,'idea_set','{"originalIdea":"Good teachers encourage shy students to share their ideas.","accurateParaphrases":["Good teachers give quiet students the confidence to say what they think.","Shy students are supported by good teachers to express their ideas.","Good teachers help timid students feel able to speak up."],"meaningInvariants":[{"type":"meaning","value":"give support and confidence"}],"distractors":[{"text":"Good teachers stop shy students from sharing their ideas.","misconceptionCategory":"polarity_change"},{"text":"Shy students encourage good teachers to share their ideas.","misconceptionCategory":"role_reversal"},{"text":"Good teachers force shy students to share their ideas.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_encourage"],"primaryEvidenceTargetId":"vocab_encourage"}'::jsonb,'live'),
('u10_idea_reflect',10,'idea_set','{"originalIdea":"At the end of the project, students reflect on what went well.","accurateParaphrases":["When the project is finished, students think carefully about what worked.","Students consider the successful parts of their project once it is over.","After the project, students look back and think about its strengths."],"meaningInvariants":[{"type":"meaning","value":"think carefully about"}],"distractors":[{"text":"At the end of the project, students forget about what went well.","misconceptionCategory":"polarity_change"},{"text":"At the start of the project, students think about what will go well.","misconceptionCategory":"time_change"},{"text":"At the end of the project, students complain about what went badly.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_reflect_10"],"primaryEvidenceTargetId":"vocab_reflect_10"}'::jsonb,'live'),
('u10_idea_performance',10,'idea_set','{"originalIdea":"Lack of sleep had a bad effect on his performance in the exam.","accurateParaphrases":["Because he had not slept enough, he did badly in the exam.","Not sleeping enough made him do worse in the exam.","He did not do as well in the exam because he was short of sleep."],"meaningInvariants":[{"type":"cause_effect","value":"poor sleep led to a worse result"}],"distractors":[{"text":"Lack of sleep had a good effect on how well he did in the exam.","misconceptionCategory":"polarity_change"},{"text":"His poor exam result caused him to lose sleep.","misconceptionCategory":"cause_change"},{"text":"Lack of sleep had a bad effect on his attendance at the exam.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_performance"],"primaryEvidenceTargetId":"vocab_performance"}'::jsonb,'live'),
('u10_idea_confidence',10,'idea_set','{"originalIdea":"Joining the drama club gave her the confidence to speak in public.","accurateParaphrases":["After joining the drama club, she felt able to speak in front of people.","The drama club helped her believe she could talk to an audience.","Being in the drama club made her feel sure enough to speak publicly."],"meaningInvariants":[{"type":"meaning","value":"belief in her ability"}],"distractors":[{"text":"Joining the drama club made her too nervous to speak in public.","misconceptionCategory":"polarity_change"},{"text":"Joining the drama club gave her the money to speak in public.","misconceptionCategory":"meaning_confusion"},{"text":"Joining the drama club might give her the courage to speak in public.","misconceptionCategory":"certainty_change"}],"linkedVocabularyIds":["vocab_confidence_10"],"primaryEvidenceTargetId":"vocab_confidence_10"}'::jsonb,'live'),
('u10_idea_contribute',10,'idea_set','{"originalIdea":"Every member of the group should contribute ideas to the project.","accurateParaphrases":["Each person in the group ought to give ideas for the project.","All group members are expected to offer suggestions for the project.","Nobody in the group should leave it to others to come up with ideas."],"meaningInvariants":[{"type":"meaning","value":"everyone gives ideas"}],"distractors":[{"text":"Only the leader of the group should contribute ideas to the project.","misconceptionCategory":"scope_change"},{"text":"Every member of the group should take ideas from other projects.","misconceptionCategory":"meaning_confusion"},{"text":"No member of the group should give ideas to the project.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_contribute_10"],"primaryEvidenceTargetId":"vocab_contribute_10"}'::jsonb,'live'),
('u10_idea_condition',10,'idea_set','{"originalIdea":"You can borrow the laptop on condition that you return it by Friday.","accurateParaphrases":["You may borrow the laptop only if you give it back by Friday.","The laptop can be borrowed as long as it comes back by Friday.","If you promise to bring it back by Friday, you can borrow the laptop."],"meaningInvariants":[{"type":"meaning","value":"only if"}],"distractors":[{"text":"You can borrow the laptop even if you return it after Friday.","misconceptionCategory":"polarity_change"},{"text":"You can borrow the laptop because you returned it last Friday.","misconceptionCategory":"time_change"},{"text":"You must borrow the laptop and return it by Friday.","misconceptionCategory":"modality_change"}],"linkedVocabularyIds":["vocab_condition"],"primaryEvidenceTargetId":"vocab_condition"}'::jsonb,'live'),
('u10_idea_conditional',10,'idea_set','{"originalIdea":"“If I had more time, I would learn Japanese” is an example of the second conditional.","accurateParaphrases":["“If I had more time, I would learn Japanese” is a second-type if-sentence about an imagined situation.","The sentence “If I had more time, I would learn Japanese” shows the second type of if-sentence.","The structure in “If I had more time, I would learn Japanese” is the second form of if-sentence."],"meaningInvariants":[{"type":"meaning","value":"type of if-sentence"}],"distractors":[{"text":"“If I had more time, I would learn Japanese” is an example of reported speech.","misconceptionCategory":"meaning_confusion"},{"text":"“If I had more time, I would learn Japanese” is an example of a question.","misconceptionCategory":"meaning_confusion"},{"text":"“I learned Japanese when I had more time” is an example of the second type of if-sentence.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_conditional"],"primaryEvidenceTargetId":"vocab_conditional"}'::jsonb,'live'),
('u10_idea_preparation',10,'idea_set','{"originalIdea":"Good preparation is the key to doing well in exams.","accurateParaphrases":["Getting ready properly is the most important thing for exam success.","If you want to do well in exams, you must plan and revise in advance.","Careful revision and planning before exams is what leads to good results."],"meaningInvariants":[{"type":"meaning","value":"getting ready in advance"}],"distractors":[{"text":"Good luck is the key to doing well in exams.","misconceptionCategory":"meaning_confusion"},{"text":"Good preparation makes no difference to how well you do in exams.","misconceptionCategory":"polarity_change"},{"text":"Good preparation is one small part of doing well in exams.","misconceptionCategory":"degree_change"}],"linkedVocabularyIds":["vocab_preparation"],"primaryEvidenceTargetId":"vocab_preparation"}'::jsonb,'live'),
('u10_idea_employment',10,'idea_set','{"originalIdea":"Most engineering graduates find employment within six months.","accurateParaphrases":["The majority of engineering graduates get a paid job within half a year.","Within six months, most people with engineering degrees are working.","Most engineering graduates start paid work less than six months after finishing."],"meaningInvariants":[{"type":"quantity","value":"most within six months"}],"distractors":[{"text":"Few engineering graduates find work within six months.","misconceptionCategory":"quantity_change"},{"text":"Most engineering graduates find a flat within six months.","misconceptionCategory":"meaning_confusion"},{"text":"Most engineering graduates find work within six years.","misconceptionCategory":"detail_change"}],"linkedVocabularyIds":["vocab_employment_10"],"primaryEvidenceTargetId":"vocab_employment_10"}'::jsonb,'live'),
('u10_idea_career',10,'idea_set','{"originalIdea":"She wants a career in medicine, so she is studying biology.","accurateParaphrases":["She is studying biology because she hopes to work in medicine for her working life.","Her plan is to become a doctor, which is why she is taking biology.","She is studying biology because her goal is a long-term job in medicine."],"meaningInvariants":[{"type":"cause_effect","value":"future job explains study choice"}],"distractors":[{"text":"She wants a hobby in medicine, so she is studying biology.","misconceptionCategory":"meaning_confusion"},{"text":"She is studying medicine, so she wants a job in biology.","misconceptionCategory":"role_reversal"},{"text":"She does not want to work in medicine, so she is studying biology.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_career"],"primaryEvidenceTargetId":"vocab_career"}'::jsonb,'live'),
('u10_idea_subject',10,'idea_set','{"originalIdea":"Maths is my favourite subject because I enjoy solving problems.","accurateParaphrases":["Of all the things I study at school, I like maths best because I enjoy solving problems.","I like maths more than anything else I study, because problem-solving is fun.","Because I love working out problems, maths is the area of study I prefer."],"meaningInvariants":[{"type":"meaning","value":"area of study"}],"distractors":[{"text":"Maths is my favourite teacher because I enjoy solving problems.","misconceptionCategory":"meaning_confusion"},{"text":"Maths is my least favourite subject because I enjoy solving problems.","misconceptionCategory":"polarity_change"},{"text":"Maths was my favourite subject because I enjoyed solving problems.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_subject"],"primaryEvidenceTargetId":"vocab_subject"}'::jsonb,'live'),
('u10_idea_aspect',10,'idea_set','{"originalIdea":"The social aspect of university is as important as studying.","accurateParaphrases":["Making friends and meeting people at university matters as much as studying.","At university, social life is just as important as academic work.","The friendships you make at university are as valuable as your studies."],"meaningInvariants":[{"type":"comparison","value":"equally important"}],"distractors":[{"text":"The social side of university is less important than studying.","misconceptionCategory":"comparison_reversal"},{"text":"The social aspect of university is more important than studying.","misconceptionCategory":"comparison_reversal"},{"text":"The social aspect of school is as important as playing sport.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_aspect"],"primaryEvidenceTargetId":"vocab_aspect"}'::jsonb,'live'),
('u10_idea_industry',10,'idea_set','{"originalIdea":"The tourism industry employs thousands of people in our country.","accurateParaphrases":["Thousands of people in our country work in businesses connected with tourism.","Hotels, travel firms and other tourist businesses give jobs to thousands of people here.","In our country, tourism-related businesses provide work for thousands."],"meaningInvariants":[{"type":"meaning","value":"businesses in one area of trade"}],"distractors":[{"text":"The tourism industry employs only a few people in our country.","misconceptionCategory":"quantity_change"},{"text":"Thousands of tourists visit our country every year.","misconceptionCategory":"meaning_confusion"},{"text":"The tourism industry used to employ thousands of people in our country.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_industry"],"primaryEvidenceTargetId":"vocab_industry"}'::jsonb,'live'),
('u10_idea_interview',10,'idea_set','{"originalIdea":"All applicants will have an interview with a tutor before they are offered a place.","accurateParaphrases":["Everyone who applies will meet a tutor and answer questions before being offered a place.","Before a place is offered, each applicant will be questioned by a tutor.","Applicants must have a formal meeting with a tutor to get a place."],"meaningInvariants":[{"type":"meaning","value":"formal meeting with questions"}],"distractors":[{"text":"All applicants will have a written exam before they are offered a place.","misconceptionCategory":"meaning_confusion"},{"text":"Only some applicants will meet a tutor before they are offered a place.","misconceptionCategory":"scope_change"},{"text":"All tutors will have an interview with an applicant before they get a job.","misconceptionCategory":"role_reversal"}],"linkedVocabularyIds":["vocab_interview"],"primaryEvidenceTargetId":"vocab_interview"}'::jsonb,'live'),
('u10_idea_overseas',10,'idea_set','{"originalIdea":"The university welcomes overseas students from more than eighty countries.","accurateParaphrases":["Students from over eighty foreign countries are welcome at the university.","The university accepts international students from more than eighty nations.","People from more than eighty other countries come to study at the university."],"meaningInvariants":[{"type":"meaning","value":"from other countries"}],"distractors":[{"text":"The university welcomes local students from more than eighty towns.","misconceptionCategory":"meaning_confusion"},{"text":"The university welcomes foreign students from fewer than eight countries.","misconceptionCategory":"quantity_change"},{"text":"The university does not accept students from other countries.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_overseas"],"primaryEvidenceTargetId":"vocab_overseas"}'::jsonb,'live'),
('u10_idea_challenge',10,'idea_set','{"originalIdea":"Moving to a new country was a big challenge for Aisha.","accurateParaphrases":["Moving to a new country was very difficult for Aisha.","Aisha found it really hard to move to a different country.","For Aisha, living in a new country was a real test of her abilities."],"meaningInvariants":[{"type":"meaning","value":"something difficult"}],"distractors":[{"text":"Moving to a new country was very easy for Aisha.","misconceptionCategory":"polarity_change"},{"text":"Moving to a new country was a big reward for Aisha.","misconceptionCategory":"meaning_confusion"},{"text":"Moving to a new country will be a small problem for Aisha.","misconceptionCategory":"degree_change"}],"linkedVocabularyIds":["vocab_challenge_10"],"primaryEvidenceTargetId":"vocab_challenge_10"}'::jsonb,'live'),
('u10_idea_reluctant',10,'idea_set','{"originalIdea":"Many students are reluctant to speak English in front of the class.","accurateParaphrases":["A lot of students do not want to speak English in front of their classmates.","Many learners are unwilling to use English when the whole class is listening.","Speaking English in front of the class is something many students would prefer to avoid."],"meaningInvariants":[{"type":"meaning","value":"unwilling"}],"distractors":[{"text":"Many students are eager to speak English in front of the class.","misconceptionCategory":"polarity_change"},{"text":"Many students are unable to speak English at all.","misconceptionCategory":"meaning_confusion"},{"text":"A few students are unwilling to speak English in front of the class.","misconceptionCategory":"quantity_change"}],"linkedVocabularyIds":["vocab_reluctant"],"primaryEvidenceTargetId":"vocab_reluctant"}'::jsonb,'live'),
('u10_idea_cosmopolitan',10,'idea_set','{"originalIdea":"London is a cosmopolitan city where you can hear hundreds of languages.","accurateParaphrases":["London has people from so many cultures that hundreds of languages are spoken there.","People from all over the world live in London, so you hear many languages.","London is a multicultural city with hundreds of languages."],"meaningInvariants":[{"type":"meaning","value":"many cultures"}],"distractors":[{"text":"London is an old-fashioned city where everyone speaks the same language.","misconceptionCategory":"polarity_change"},{"text":"London is an expensive city where you can buy hundreds of things.","misconceptionCategory":"meaning_confusion"},{"text":"London is a small city where you can hear a few languages.","misconceptionCategory":"quantity_change"}],"linkedVocabularyIds":["vocab_cosmopolitan"],"primaryEvidenceTargetId":"vocab_cosmopolitan"}'::jsonb,'live'),
('u10_idea_assignment',10,'idea_set','{"originalIdea":"The history assignment must be handed in by Friday.","accurateParaphrases":["You need to give your history coursework to the teacher by Friday.","The piece of history work we were set is due on Friday.","Friday is the deadline for the history task."],"meaningInvariants":[{"type":"meaning","value":"set piece of work"}],"distractors":[{"text":"The history assignment can be handed in any time next month.","misconceptionCategory":"detail_change"},{"text":"The history test will take place on Friday.","misconceptionCategory":"meaning_confusion"},{"text":"The history teacher must give back our work by Friday.","misconceptionCategory":"role_reversal"}],"linkedVocabularyIds":["vocab_assignment_10"],"primaryEvidenceTargetId":"vocab_assignment_10"}'::jsonb,'live'),
('u10_idea_loneliness',10,'idea_set','{"originalIdea":"Many overseas students experience loneliness in their first weeks.","accurateParaphrases":["A lot of students from abroad feel alone during their first few weeks.","In the first weeks, many international students feel isolated and miss people.","Many students who come from other countries feel lonely at first."],"meaningInvariants":[{"type":"meaning","value":"feeling alone"}],"distractors":[{"text":"Many overseas students feel excited in their first weeks.","misconceptionCategory":"meaning_confusion"},{"text":"Few overseas students feel alone in their first weeks.","misconceptionCategory":"quantity_change"},{"text":"Many overseas students feel alone in their final weeks.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_loneliness"],"primaryEvidenceTargetId":"vocab_loneliness"}'::jsonb,'live'),
('u10_idea_opportunity',10,'idea_set','{"originalIdea":"Studying abroad gave her the opportunity to learn a new language.","accurateParaphrases":["Because she studied abroad, she had the chance to learn another language.","Studying in another country made it possible for her to learn a new language.","Her time studying abroad let her pick up a new language."],"meaningInvariants":[{"type":"meaning","value":"chance"}],"distractors":[{"text":"Studying abroad stopped her from learning a new language.","misconceptionCategory":"polarity_change"},{"text":"Studying abroad forced her to forget her own language.","misconceptionCategory":"meaning_confusion"},{"text":"Learning a new language gave her the chance to study abroad.","misconceptionCategory":"cause_change"}],"linkedVocabularyIds":["vocab_opportunity"],"primaryEvidenceTargetId":"vocab_opportunity"}'::jsonb,'live'),
('u10_idea_examination',10,'idea_set','{"originalIdea":"All students must take a written examination at the end of the course.","accurateParaphrases":["Every student has to sit a formal written test when the course finishes.","At the end of the course, everyone must do a written exam.","There is a compulsory written exam for all students at the end."],"meaningInvariants":[{"type":"meaning","value":"formal test"}],"distractors":[{"text":"Some students may take a written examination at the start of the course.","misconceptionCategory":"time_change"},{"text":"All students must write a letter at the end of the course.","misconceptionCategory":"meaning_confusion"},{"text":"No students have to take a written test at the end of the course.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_examination"],"primaryEvidenceTargetId":"vocab_examination"}'::jsonb,'live'),
('u10_idea_research',10,'idea_set','{"originalIdea":"Research shows that students who sleep well remember more.","accurateParaphrases":["Studies show that students who get good sleep remember more.","Scientific investigation has found that well-rested students remember more.","According to studies, good sleep helps students remember more."],"meaningInvariants":[{"type":"meaning","value":"detailed study"}],"distractors":[{"text":"Rumours suggest that students who sleep well remember more.","misconceptionCategory":"certainty_change"},{"text":"Research shows that students who sleep well remember less.","misconceptionCategory":"polarity_change"},{"text":"Research shows that students who remember more sleep well.","misconceptionCategory":"cause_change"}],"linkedVocabularyIds":["vocab_research_10"],"primaryEvidenceTargetId":"vocab_research_10"}'::jsonb,'live'),
('u10_idea_presentation',10,'idea_set','{"originalIdea":"Each student will give a five-minute presentation about a famous scientist.","accurateParaphrases":["Every student will talk to the class for five minutes about a well-known scientist.","Each student must speak for five minutes about a famous scientist.","All students will present a short five-minute talk on a famous scientist."],"meaningInvariants":[{"type":"meaning","value":"talk to an audience"}],"distractors":[{"text":"Each student will write a five-page essay about a famous scientist.","misconceptionCategory":"meaning_confusion"},{"text":"A famous scientist will give a five-minute talk to each student.","misconceptionCategory":"role_reversal"},{"text":"Each student will give a fifty-minute talk about a famous scientist.","misconceptionCategory":"quantity_change"}],"linkedVocabularyIds":["vocab_presentation"],"primaryEvidenceTargetId":"vocab_presentation"}'::jsonb,'live'),
('u10_idea_pronunciation',10,'idea_set','{"originalIdea":"Her grammar is excellent, but her pronunciation needs work.","accurateParaphrases":["Her grammar is very good, but the way she says words needs improving.","Although her grammar is excellent, she needs to practise how she speaks words.","She has excellent grammar but must improve how she says English words."],"meaningInvariants":[{"type":"contrast","value":"good grammar, weaker speaking"}],"distractors":[{"text":"Her grammar is excellent, and the way she says words is perfect.","misconceptionCategory":"polarity_change"},{"text":"Her grammar is excellent, but her spelling needs work.","misconceptionCategory":"meaning_confusion"},{"text":"Her grammar needs work, but the way she says words is excellent.","misconceptionCategory":"comparison_reversal"}],"linkedVocabularyIds":["vocab_pronunciation"],"primaryEvidenceTargetId":"vocab_pronunciation"}'::jsonb,'live'),
('u10_idea_intonation',10,'idea_set','{"originalIdea":"Rising intonation at the end of a sentence often shows that it is a question.","accurateParaphrases":["When your voice goes up at the end of a sentence, it often means you are asking a question.","A question is often shown by the voice rising at the end.","If the voice goes up at the end, the sentence is often a question."],"meaningInvariants":[{"type":"meaning","value":"rise and fall of the voice"}],"distractors":[{"text":"Rising volume at the end of a sentence always shows anger.","misconceptionCategory":"meaning_confusion"},{"text":"Falling voice at the end of a sentence often shows that it is a question.","misconceptionCategory":"polarity_change"},{"text":"A question mark at the end of a sentence often shows that it is a question.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_intonation"],"primaryEvidenceTargetId":"vocab_intonation"}'::jsonb,'live'),
('u10_idea_vocabulary',10,'idea_set','{"originalIdea":"Reading widely is the best way to increase your vocabulary.","accurateParaphrases":["The best way to learn more words is to read a lot of different things.","If you read many different kinds of text, you will learn more words.","Reading a wide range of texts is the most effective way to know more words."],"meaningInvariants":[{"type":"meaning","value":"words you know"}],"distractors":[{"text":"Reading widely is the best way to improve your handwriting.","misconceptionCategory":"meaning_confusion"},{"text":"Reading widely is one of the worst ways to learn new words.","misconceptionCategory":"polarity_change"},{"text":"Reading widely may be a way to learn more words.","misconceptionCategory":"certainty_change"}],"linkedVocabularyIds":["vocab_vocabulary"],"primaryEvidenceTargetId":"vocab_vocabulary"}'::jsonb,'live'),
('u10_idea_accurately',10,'idea_set','{"originalIdea":"You must measure each liquid accurately in the experiment.","accurateParaphrases":["In the experiment, you have to measure every liquid exactly.","Each liquid must be measured correctly, without mistakes, in the experiment.","Measure all the liquids precisely when you do the experiment."],"meaningInvariants":[{"type":"meaning","value":"exactly, without mistakes"}],"distractors":[{"text":"You must measure each liquid quickly in the experiment.","misconceptionCategory":"meaning_confusion"},{"text":"You do not need to measure each liquid exactly in the experiment.","misconceptionCategory":"polarity_change"},{"text":"You can measure each liquid roughly in the experiment.","misconceptionCategory":"degree_change"}],"linkedVocabularyIds":["vocab_accurately"],"primaryEvidenceTargetId":"vocab_accurately"}'::jsonb,'live'),
('u10_idea_effectively',10,'idea_set','{"originalIdea":"Good students learn to manage their time effectively.","accurateParaphrases":["Good students learn to use their time in a way that works well.","Successful students learn how to organise their time well.","Good students find out how to plan their time so that it produces results."],"meaningInvariants":[{"type":"meaning","value":"in a way that works"}],"distractors":[{"text":"Good students learn to manage their time slowly.","misconceptionCategory":"meaning_confusion"},{"text":"Good students never learn to organise their time.","misconceptionCategory":"polarity_change"},{"text":"Good teachers learn to manage students’ time well.","misconceptionCategory":"role_change"}],"linkedVocabularyIds":["vocab_effectively"],"primaryEvidenceTargetId":"vocab_effectively"}'::jsonb,'live'),
('u10_idea_evaluate',10,'idea_set','{"originalIdea":"Students must evaluate each source before using it in an essay.","accurateParaphrases":["Before using a source in an essay, students have to judge how good and reliable it is.","Students need to check how trustworthy each source is before they use it.","Every source should be assessed by students before it appears in an essay."],"meaningInvariants":[{"type":"meaning","value":"judge the quality"}],"distractors":[{"text":"Students must copy each source before using it in an essay.","misconceptionCategory":"meaning_confusion"},{"text":"Students do not need to check sources before using them.","misconceptionCategory":"polarity_change"},{"text":"Teachers must judge each essay before students use a source.","misconceptionCategory":"role_reversal"}],"linkedVocabularyIds":["vocab_evaluate_10"],"primaryEvidenceTargetId":"vocab_evaluate_10"}'::jsonb,'live'),
('u10_idea_develop',10,'idea_set','{"originalIdea":"The course helps students develop their speaking skills.","accurateParaphrases":["The course helps students improve their speaking skills.","Students build up their speaking ability on this course.","On the course, students’ speaking skills get stronger."],"meaningInvariants":[{"type":"meaning","value":"improve over time"}],"distractors":[{"text":"The course helps students test their speaking skills once.","misconceptionCategory":"meaning_confusion"},{"text":"The course makes students’ speaking skills weaker.","misconceptionCategory":"polarity_change"},{"text":"The course helps teachers improve their writing skills.","misconceptionCategory":"role_change"}],"linkedVocabularyIds":["vocab_develop"],"primaryEvidenceTargetId":"vocab_develop"}'::jsonb,'live'),
('u10_idea_communicate',10,'idea_set','{"originalIdea":"Overseas students quickly learn to communicate in English.","accurateParaphrases":["Students from abroad soon learn to share their ideas in English.","International students quickly become able to talk with others in English.","Before long, foreign students can express themselves in English."],"meaningInvariants":[{"type":"meaning","value":"share ideas"}],"distractors":[{"text":"Overseas students quickly learn to write poems in English.","misconceptionCategory":"meaning_confusion"},{"text":"Overseas students slowly learn to speak in English.","misconceptionCategory":"degree_change"},{"text":"Overseas students never learn to talk with others in English.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_communicate_10"],"primaryEvidenceTargetId":"vocab_communicate_10"}'::jsonb,'live'),
('u10_idea_opinion',10,'idea_set','{"originalIdea":"In my opinion, school uniforms help students feel equal.","accurateParaphrases":["I think school uniforms make students feel equal.","My view is that uniforms help everyone at school feel the same.","I believe that wearing a uniform makes students feel equal."],"meaningInvariants":[{"type":"meaning","value":"personal view"}],"distractors":[{"text":"It is a proven fact that school uniforms help students feel equal.","misconceptionCategory":"certainty_change"},{"text":"In my opinion, school uniforms make students feel unequal.","misconceptionCategory":"polarity_change"},{"text":"In my opinion, school uniforms help teachers feel equal.","misconceptionCategory":"role_change"}],"linkedVocabularyIds":["vocab_opinion"],"primaryEvidenceTargetId":"vocab_opinion"}'::jsonb,'live'),
('u10_idea_preference',10,'idea_set','{"originalIdea":"Many employers show a preference for applicants with work experience.","accurateParaphrases":["A lot of employers would rather choose applicants who have worked before.","Many employers like applicants with work experience more than those without it.","Applicants who have already worked are often favoured by employers."],"meaningInvariants":[{"type":"meaning","value":"liking one thing more"}],"distractors":[{"text":"Many employers refuse to hire applicants with work experience.","misconceptionCategory":"polarity_change"},{"text":"Many applicants prefer employers with work experience.","misconceptionCategory":"role_reversal"},{"text":"Every employer requires applicants to have a degree.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_preference_10"],"primaryEvidenceTargetId":"vocab_preference_10"}'::jsonb,'live'),
('u10_idea_discussion',10,'idea_set','{"originalIdea":"The class had a lively discussion about banning homework.","accurateParaphrases":["The students talked energetically and shared views on banning homework.","There was an animated class conversation about whether to ban homework.","The class exchanged lots of opinions about banning homework."],"meaningInvariants":[{"type":"meaning","value":"talk to share views"}],"distractors":[{"text":"The class wrote a quiet test about banning homework.","misconceptionCategory":"meaning_confusion"},{"text":"The class had a short, boring talk about banning homework.","misconceptionCategory":"degree_change"},{"text":"The teacher gave a speech about banning homework while the class listened silently.","misconceptionCategory":"role_change"}],"linkedVocabularyIds":["vocab_discussion"],"primaryEvidenceTargetId":"vocab_discussion"}'::jsonb,'live'),
('u10_idea_achievement',10,'idea_set','{"originalIdea":"Passing all her exams was a great achievement after such a difficult year.","accurateParaphrases":["After such a hard year, passing all her exams was a great success.","She did something really impressive by passing every exam in such a difficult year.","Getting through all her exams after a tough year was a big accomplishment."],"meaningInvariants":[{"type":"meaning","value":"difficult success"}],"distractors":[{"text":"Failing all her exams was a great disappointment after such a difficult year.","misconceptionCategory":"polarity_change"},{"text":"Passing all her exams was easy after such a relaxing year.","misconceptionCategory":"meaning_confusion"},{"text":"Passing one of her exams was a small success after an easy year.","misconceptionCategory":"quantity_change"}],"linkedVocabularyIds":["vocab_achievement_10"],"primaryEvidenceTargetId":"vocab_achievement_10"}'::jsonb,'live'),
('u10_idea_qualification',10,'idea_set','{"originalIdea":"You need a teaching qualification to work in a state school.","accurateParaphrases":["To teach in a state school, you must have a teaching certificate.","State schools only employ teachers who have completed a teacher-training course.","A teaching certificate is required for work in a state school."],"meaningInvariants":[{"type":"meaning","value":"official certificate"}],"distractors":[{"text":"You need a teaching uniform to work in a state school.","misconceptionCategory":"meaning_confusion"},{"text":"You do not need any certificate to teach in a state school.","misconceptionCategory":"polarity_change"},{"text":"You need teaching experience abroad to work in a state school.","misconceptionCategory":"detail_change"}],"linkedVocabularyIds":["vocab_qualification_10"],"primaryEvidenceTargetId":"vocab_qualification_10"}'::jsonb,'live'),
('u10_idea_succeed',10,'idea_set','{"originalIdea":"If you work hard and ask for help, you will succeed.","accurateParaphrases":["Working hard and asking for help will lead you to do well.","You will achieve your goals if you work hard and get help.","Hard work and asking for support will bring you success."],"meaningInvariants":[{"type":"cause_effect","value":"effort leads to success"}],"distractors":[{"text":"If you work hard and ask for help, you will fail.","misconceptionCategory":"polarity_change"},{"text":"If you work hard and ask for help, you might do well.","misconceptionCategory":"certainty_change"},{"text":"If you do well, you will work hard and ask for help.","misconceptionCategory":"cause_change"}],"linkedVocabularyIds":["vocab_succeed"],"primaryEvidenceTargetId":"vocab_succeed"}'::jsonb,'live'),
